8	import { ImageResult } from './ImageResult';
9	import { InpaintCanvas } from './InpaintCanvas';
10	import { PhotoGallery } from './PhotoGallery';
11	
12	export interface PhotoMagicViewProps {
13	  /** Optional initial prompt passed from voice command or taskbar */
14	  initialPrompt?: string;
15	}
16	
17	export default function PhotoMagicView({ initialPrompt }: PhotoMagicViewProps) {
18	  const {
19	    state,
20	    progress,
21	    progressText,
22	    result,
23	    error,
24	    sourceImage,
25	    prompt: activePrompt,
26	    generate,
27	    inpaint,
28	    reset,
29	    editAgain,
